# region: gather
def gather(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(digest(emit(shape(gather(raw)))))

